{"cards": [{"node_code": "N_ea47e13a9d3aa5fc", "definition": "研究线性含源二端网络等效简化方法的学科，涵盖戴维南定理（电压源串联电阻）与诺顿定理（电流源并联电阻）的推导、应用及等效参数计算。", "boundary": "聚焦于将复杂线性含源网络简化为单一电压源或电流源与内阻组合的等效模型。包括开路电压/短路电流的求解、等效内阻的计算（独立源置零法或外加电源法）及等效电路的构建。若内容涉及非线性元件的局部线性化或动态电路的瞬态响应求解，则不在此列。", "includes": ["戴维南等效电路的构建与开路电压、等效电阻计算", "诺顿等效电路的构建与短路电流、等效电导计算", "戴维南与诺顿等效电路之间的转换关系及适用条件"], "excludes": ["非线性电路的等效分析或局部线性化方法", "含受控源网络中受控源处理的具体技巧（若未涉及等效模型构建）"], "sibling_distinctions": [{"other_code": "N_5e98e23cfc01cfb4", "rule": "本节点关注网络结构的整体等效替换（源+阻抗）；兄弟节点关注利用线性性质分解响应（叠加）或能量/对偶关系（特勒根）。"}, {"other_code": "N_6747877dacc90007", "rule": "本节点关注网络等效模型的建立；兄弟节点关注基于等效模型或网络对称性进行的功率优化与参数互易性分析。"}], "cross_boundary_rule": "若内容核心在于将复杂网络简化为简单等效源模型，归入本节点；若核心在于利用等效模型进行后续功率计算或互易性验证，归入最大功率传输与互易定理节点。"}, {"node_code": "N_5e98e23cfc01cfb4", "definition": "研究线性电路响应分解及网络能量/对偶性质的学科，涵盖叠加定理（多源线性叠加）与特勒根定理（功率守恒与对偶性）的理论及应用。", "boundary": "聚焦于利用线性系统的齐次性和可加性进行多激励响应的分解计算，以及基于网络拓扑与支路电压电流乘积和的能量守恒或对偶关系分析。包括叠加定理的适用条件（线性元件）、特勒根定理的普适性（含非线性、时变网络）及对偶网络概念。若内容涉及具体微分方程求解或单一源的等效替换，则不在此列。", "includes": ["叠加定理在多独立源线性电路中的应用及线性/非线性元件限制", "特勒根定理的表述、证明及其在功率平衡分析中的应用", "对偶网络的概念、构建方法及对偶定理的应用"], "excludes": ["戴维南/诺顿等效电路的构建过程", "动态电路时域微分方程的具体求解步骤"], "sibling_distinctions": [{"other_code": "N_ea47e13a9d3aa5fc", "rule": "本节点关注响应的线性分解（叠加）或能量/对偶性质（特勒根）；兄弟节点关注网络结构的整体等效替换（戴维南/诺顿）。"}, {"other_code": "N_6747877dacc90007", "rule": "本节点关注线性分解与能量/对偶基础理论；兄弟节点关注基于网络参数对称性的互易性及功率传输极值问题。"}], "cross_boundary_rule": "若内容侧重于多源响应的线性叠加计算或功率守恒/对偶性证明，归入本节点；若侧重于利用互易性简化参数计算或功率匹配，归入最大功率传输与互易定理节点。"}, {"node_code": "N_6747877dacc90007", "definition": "研究线性网络功率传输极值条件及参数对称性关系的学科，涵盖最大功率传输定理（阻抗匹配）与互易定理（电压/电流比对称性）的理论及应用。", "boundary": "聚焦于负载获得最大功率的条件（共轭匹配或电阻匹配）及最大值的计算，以及线性无源网络中激励与响应位置互换时参数保持不变的互易性分析。包括互易定理的三种形式（电压、电流、混合）及在二端口网络参数（Z、Y、ABCD）中的应用。若内容涉及非线性元件或含受控源网络的互易性破坏分析，则不在此列。", "includes": ["最大功率传输定理的推导、阻抗匹配条件及最大功率计算", "互易定理的表述、证明及其在二端口网络参数对称性中的应用", "互易网络与非互易网络的判别及受控源对互易性的影响"], "excludes": ["戴维南/诺顿等效电路的构建过程", "叠加定理在多源响应分解中的具体应用"], "sibling_distinctions": [{"other_code": "N_ea47e13a9d3aa5fc", "rule": "本节点关注功率极值与参数对称性；兄弟节点关注网络等效模型的建立。"}, {"other_code": "N_5e98e23cfc01cfb4", "rule": "本节点关注功率匹配与互易性；兄弟节点关注线性叠加与能量/对偶基础。"}], "cross_boundary_rule": "若内容侧重于功率传输效率优化或网络参数对称性验证，归入本节点；若侧重于等效模型构建或响应线性分解，归入相应等效或叠加节点。"}]}
